The code is for a simple banking system that allows users to create accounts, deposit money, withdraw money, and check their balance. The code uses a dictionary to store the account information, where the account number is the key and the account balance is the value.

```python
# Dictionary to store account information
accounts = {}

# Function to create a new account
def create_account(account_number, initial_balance):
    if account_number in accounts:
        print("Account already exists.")
    else:
        accounts[account_number] = initial_balance
        print("Account created successfully.")

# Function to deposit money into an account
def deposit(account_number, amount):
    if account_number not in accounts:
        print("Account does not exist.")
    else:
        accounts[account_number] += amount
        print("Deposit successful.")

# Function to withdraw money from an account
def withdraw(account_number, amount):
    if account_number not in accounts:
        print("Account does not exist.")
    elif accounts[account_number] < amount:
        print("Insufficient balance.")
    else:
        accounts[account_number] -= amount
        print("Withdrawal successful.")

# Function to check the balance of an account
def check_balance(account_number):
    if account_number not in accounts:
        print("Account does not exist.")
    else:
        print(f"Account balance: {accounts[account_number]}")

# Main function to interact with the banking system
def main():
    while True:
        print("Welcome to the banking system!")
        print("1. Create account")
        print("2. Deposit money")
        print("3. Withdraw money")
        print("4. Check balance")
        print("5. Quit")
        choice = input("Enter your choice: ")

        if choice == "1":
            account_number = input("Enter account number: ")
            initial_balance = float(input("Enter initial balance: "))
            create_account(account_number, initial_balance)
        elif choice == "2":
            account_number = input("Enter account number: ")
            amount = float(input("Enter amount to deposit: "))
            deposit(account_number, amount)
        elif choice == "3":
            account_number = input("Enter account number: ")
            amount = float(input("Enter amount to withdraw: "))
            withdraw(account_number, amount)
        elif choice == "4":
            account_number = input("Enter account number: ")
            check_balance(account_number)
        elif choice == "5":
            print("Thank you for using the banking system!")
            break
        else:
            print("Invalid choice. Please try again.")

# Call the main function to start the banking system
main()
```

