Here is the updated code with the added features of transaction history and user authentication:

```python
class BankingSystem:
    def __init__(self):
        self.accounts = {}

    # Function to create a new account
    def create_account(self, account_number, initial_balance, password):
        if account_number in self.accounts:
            print("Account already exists.")
        else:
            self.accounts[account_number] = {"balance": initial_balance, "password": password, "transaction_history": []}
            print("Account created successfully.")

    # Function to deposit money into an account
    def deposit(self, account_number, amount, password):
        if account_number not in self.accounts:
            print("Account does not exist.")
        elif self.accounts[account_number]["password"] != password:
            print("Invalid password.")
        else:
            self.accounts[account_number]["balance"] += amount
            self.accounts[account_number]["transaction_history"].append(f"Deposit: {amount}")
            print("Deposit successful.")

    # Function to withdraw money from an account
    def withdraw(self, account_number, amount, password):
        if account_number not in self.accounts:
            print("Account does not exist.")
        elif self.accounts[account_number]["password"] != password:
            print("Invalid password.")
        elif self.accounts[account_number]["balance"] < amount:
            print("Insufficient balance.")
        else:
            self.accounts[account_number]["balance"] -= amount
            self.accounts[account_number]["transaction_history"].append(f"Withdrawal: {amount}")
            print("Withdrawal successful.")

    # Function to check the balance of an account
    def check_balance(self, account_number, password):
        if account_number not in self.accounts:
            print("Account does not exist.")
        elif self.accounts[account_number]["password"] != password:
            print("Invalid password.")
        else:
            print(f"Account balance: {self.accounts[account_number]['balance']}")

    # Function to display the transaction history of an account
    def transaction_history(self, account_number, password):
        if account_number not in self.accounts:
            print("Account does not exist.")
        elif self.accounts[account_number]["password"] != password:
            print("Invalid password.")
        else:
            print("Transaction History:")
            for transaction in self.accounts[account_number]["transaction_history"]:
                print(transaction)

    # Main function to interact with the banking system
    def main(self):
        while True:
            print("Welcome to the banking system!")
            print("1. Create account")
            print("2. Deposit money")
            print("3. Withdraw money")
            print("4. Check balance")
            print("5. Transaction history")
            print("6. Quit")
            choice = input("Enter your choice: ")

            if choice == "1":
                account_number = input("Enter account number: ")
                initial_balance = float(input("Enter initial balance: "))
                password = input("Enter password: ")
                self.create_account(account_number, initial_balance, password)
            elif choice == "2":
                account_number = input("Enter account number: ")
                amount = float(input("Enter amount to deposit: "))
                password = input("Enter password: ")
                self.deposit(account_number, amount, password)
            elif choice == "3":
                account_number = input("Enter account number: ")
                amount = float(input("Enter amount to withdraw: "))
                password = input("Enter password: ")
                self.withdraw(account_number, amount, password)
            elif choice == "4":
                account_number = input("Enter account number: ")
                password = input("Enter password: ")
                self.check_balance(account_number, password)
            elif choice == "5":
                account_number = input("Enter account number: ")
                password = input("Enter password: ")
                self.transaction_history(account_number, password)
            elif choice == "6":
                print("Thank you for using the banking system!")
                break
            else:
                print("Invalid choice. Please try again.")

# Create an instance of the BankingSystem class and call the main method
banking_system = BankingSystem()
banking_system.main()
```

